-- Thermo Scientific Eutech TN-100 waterproof turbidimeter: 2 meter versions + calibration kit and cuvettes (5 products).
-- From the TN-100 product specifications. Photos: public/products/eutech/. Brand: Eutech Instruments.
-- Run in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again: products are updated by SKU.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('Eutech Instruments', 'eutech-instruments', 'https://www.eutechinst.com/')
on conflict (slug) do update set name = excluded.name, website_url = coalesce(brands.website_url, excluded.website_url);
insert into categories (name, slug, sort_order) values ('Environmental Equipment', 'environmental-equipment', 6) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('ECTN100IR', 'Eutech TN-100 Waterproof Turbidimeter Kit with Calibration Standards', 'eutech-tn-100-waterproof-turbidimeter-kit-with-calibration-standards-ectn100ir', 'The Thermo Scientific Eutech TN-100 is a lightweight, IP67 waterproof handheld turbidimeter (ISO 7027) that auto-ranges from 0 to 2000 NTU. This kit comes with a set of 4 calibration standards (800, 100, 20.0 and 0.02 NTU), 7 sample vials, lint-free cloth, silicone oil, batteries and a hard carrying case.', '[["Order code", "ECTN100IR"], ["Supplied with", "Meter, 4 calibration standards (800, 100, 20.0, 0.02 NTU), 7 sample vials, lint-free cloth, silicone oil, batteries, hard carrying case"], ["Measuring parameter", "Turbidity"], ["Principle", "Nephelometric non-ratio; ISO 7027 and DIN 27027 compliant"], ["Range", "0 to 2000 NTU (auto-ranging)"], ["Ranges", "0.01 to 19.99 NTU; 20.0 to 99.9 NTU; 100 to 2000 NTU"], ["Resolution", "0.01 NTU (0 to 19.99); 0.1 NTU (20.0 to 99.9); 1 NTU (100 to 2000)"], ["Accuracy", "< 0.1 NTU for 0.02 NTU standard; ±2 % of reading ±1 digit (0 to 500 NTU); ±3 % of reading ±1 digit (501 to 2000 NTU)"], ["Repeatability", "≤ ±1 % of reading"], ["Calibration", "Up to 4 points: 0.02, 20.0, 100 and 800 NTU"], ["Response time", "< 6 s for full step change"], ["Sample volume", "10 mL"], ["Light source", "Infrared-emitting diode, 850 nm"], ["Operating / sample temperature", "0 to 50 °C"], ["Enclosure", "ABS plastic, IP67 waterproof (floats)"], ["Power", "4 × 1.5 V AAA alkaline batteries (> 1,200 readings), auto-off"], ["Certifications", "FCC part 15 class A, TUV 3 in 1, CE, RoHS"], ["Dimensions", "Meter 15.5 × 6.8 × 4.6 cm; boxed 35.5 × 16.5 × 10.5 cm"], ["Weight", "Meter 200 g; boxed 1,160 g"], ["Warranty", "3 years"]]', '["Lightweight, ergonomic and IP67 waterproof — it floats", "Fast response: full step change in as little as 6 seconds", "Auto-ranging from 0 to 2000 NTU", "Over 1,200 tests on one set of AAA batteries, with auto-off", "Meets ISO 7027 with a consistent infrared light source", "Simple display-prompted push-button calibration", "Large LCD with units and guiding message codes", "For beverage production, drinking water, pools, aquariums, aquaculture and environmental testing"]', 'environmental-equipment', '/products/eutech/tn-100-kit.jpg'),
  ('ECTN100NOSTDS', 'Eutech TN-100 Waterproof Turbidimeter (without Calibration Standards)', 'eutech-tn-100-waterproof-turbidimeter-without-calibration-standards-ectn100nostds', 'The Thermo Scientific Eutech TN-100 is a lightweight, IP67 waterproof handheld turbidimeter (ISO 7027) that auto-ranges from 0 to 2000 NTU. This version comes with 7 sample vials, lint-free cloth, silicone oil, batteries and a hard carrying case, without calibration standards.', '[["Order code", "ECTN100NOSTDS"], ["Supplied with", "Meter, 7 sample vials, lint-free cloth, silicone oil, batteries, hard carrying case"], ["Measuring parameter", "Turbidity"], ["Principle", "Nephelometric non-ratio; ISO 7027 and DIN 27027 compliant"], ["Range", "0 to 2000 NTU (auto-ranging)"], ["Ranges", "0.01 to 19.99 NTU; 20.0 to 99.9 NTU; 100 to 2000 NTU"], ["Resolution", "0.01 NTU (0 to 19.99); 0.1 NTU (20.0 to 99.9); 1 NTU (100 to 2000)"], ["Accuracy", "< 0.1 NTU for 0.02 NTU standard; ±2 % of reading ±1 digit (0 to 500 NTU); ±3 % of reading ±1 digit (501 to 2000 NTU)"], ["Repeatability", "≤ ±1 % of reading"], ["Calibration", "Up to 4 points: 0.02, 20.0, 100 and 800 NTU"], ["Response time", "< 6 s for full step change"], ["Sample volume", "10 mL"], ["Light source", "Infrared-emitting diode, 850 nm"], ["Operating / sample temperature", "0 to 50 °C"], ["Enclosure", "ABS plastic, IP67 waterproof (floats)"], ["Power", "4 × 1.5 V AAA alkaline batteries (> 1,200 readings), auto-off"], ["Certifications", "FCC part 15 class A, TUV 3 in 1, CE, RoHS"], ["Dimensions", "Meter 15.5 × 6.8 × 4.6 cm; boxed 35.5 × 16.5 × 10.5 cm"], ["Weight", "Meter 200 g; boxed 1,160 g"], ["Warranty", "3 years"]]', '["Lightweight, ergonomic and IP67 waterproof — it floats", "Fast response: full step change in as little as 6 seconds", "Auto-ranging from 0 to 2000 NTU", "Over 1,200 tests on one set of AAA batteries, with auto-off", "Meets ISO 7027 with a consistent infrared light source", "Simple display-prompted push-button calibration", "Large LCD with units and guiding message codes", "For beverage production, drinking water, pools, aquariums, aquaculture and environmental testing"]', 'environmental-equipment', '/products/eutech/tn-100.jpg'),
  ('TN100CALKIT', 'Eutech TN-100 Turbidity Calibration Kit (0.02, 20.0, 100, 800 NTU)', 'eutech-tn-100-turbidity-calibration-kit-0-02-20-0-100-800-ntu-tn100calkit', 'Calibration kit for the Eutech TN-100 turbidimeter: four 60 mL bottles of US EPA-approved, stable non-formazin standards (0.02, 20.0, 100 and 800 NTU) and 4 vials.', '[["Order code", "TN100CALKIT"], ["Contents", "0.02, 20.0, 100 and 800 NTU standards, 60 mL each, and 4 vials"], ["Type", "US EPA-approved non-formazin standards"], ["For", "Eutech TN-100 turbidimeter"]]', '[]', 'environmental-equipment', '/products/eutech/tn-100-calibration-kit.jpg'),
  ('ECTN100CUVKIT', 'Eutech TN-100 Sample Cuvettes, Pack of 3', 'eutech-tn-100-sample-cuvettes-pack-of-3-ectn100cuvkit', 'Replacement borosilicate sample cuvettes (vials) with light shield caps for the Eutech TN-100 turbidimeter. Index markings make repeatable measurements easy.', '[["Order code", "ECTN100CUVKIT"], ["Pack size", "3 cuvettes (vials)"], ["For", "Eutech TN-100 turbidimeter"]]', '[]', 'environmental-equipment', '/products/eutech/tn-100-cuvettes.jpg'),
  ('ECTN100CUVKIT4', 'Eutech TN-100 Sample Cuvettes, Pack of 4', 'eutech-tn-100-sample-cuvettes-pack-of-4-ectn100cuvkit4', 'Replacement borosilicate sample cuvettes (vials) with light shield caps for the Eutech TN-100 turbidimeter. Index markings make repeatable measurements easy.', '[["Order code", "ECTN100CUVKIT4"], ["Pack size", "4 cuvettes (vials)"], ["For", "Eutech TN-100 turbidimeter"]]', '[]', 'environmental-equipment', '/products/eutech/tn-100-cuvettes.jpg')
) as v(sku, name, slug, description, specs, features, cat, image_url)
join categories c on c.slug = v.cat
cross join (select id from brands where slug = 'eutech-instruments') b
on conflict (sku) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, specs = excluded.specs,
  features = excluded.features, category_id = excluded.category_id, brand_id = excluded.brand_id, image_url = excluded.image_url, is_active = true;

select count(*) as products from products p join brands b on b.id = p.brand_id where b.slug = 'eutech-instruments' and p.is_active;
